10	//
11	//	magic   4 bytes  "BCL1"
12	//	seq     8 bytes  batch sequence number
13	//	count   4 bytes  number of records
14	//	records count × (4-byte length + opaque bytes)
15	//	crc32   4 bytes  IEEE checksum of everything before it
16	//
17	// The trailing checksum makes tampering detectable as ErrCorruptSegment
18	// when the segment is parsed. A torn write left by a crash is instead
19	// reported as a tail: a strict prefix of a valid entry, never a full
20	// entry with a bad checksum.
21	var segmentMagic = []byte{'B', 'C', 'L', '1'}
22	
