26		size := entryHeaderLen + 4
27		for _, r := range records {
28			size += 4 + len(r)
29		}
30		buf := make([]byte, 0, size)
31		buf = append(buf, segmentMagic...)
32		var tmp [8]byte
33		binary.LittleEndian.PutUint64(tmp[:], seq)
34		buf = append(buf, tmp[:]...)
35		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(records)))
36		buf = append(buf, tmp[:4]...)
37		for _, r := range records {
38			binary.LittleEndian.PutUint32(tmp[:4], uint32(len(r)))
39			buf = append(buf, tmp[:4]...)
40			buf = append(buf, r...)
41		}
42		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
43		return append(buf, tmp[:4]...)
44	}
45	
46	type parsedBatch struct {
47		seq     uint64
48		records [][]byte
49	}
50	
51	// segmentTail describes an incomplete entry at the end of a segment: the
52	// remnant of a crash in the middle of a write.
53	type segmentTail struct {
54		off    int    // offset where the incomplete entry starts
55		seq    uint64 // sequence reserved for the crashed batch
56		hasSeq bool   // whether the partial header held a full sequence
57	}
58	
59	// parseSegment decodes every complete batch entry in data. A truncated
60	// tail — trailing bytes that are only a prefix of an entry — is reported
61	// separately as the signature of a crash mid-write. Any other
62	// inconsistency (unknown magic, bad checksum) yields ErrCorruptSegment.
63	func parseSegment(data []byte) ([]parsedBatch, *segmentTail, error) {
64		var batches []parsedBatch
65		off := 0
66		for off < len(data) {
67			rest := data[off:]
68			if len(rest) < entryHeaderLen {
69				// A partial header is a torn write only if it is a
70				// prefix of a valid header.
71				n := min(len(rest), len(segmentMagic))
72				if !bytes.Equal(rest[:n], segmentMagic[:n]) {
73					return nil, nil, ErrCorruptSegment
74				}
75				tail := &segmentTail{off: off}
