77					tail.seq = binary.LittleEndian.Uint64(rest[4:12])
78					tail.hasSeq = true
79				}
80				return batches, tail, nil
81			}
82			if !bytes.Equal(rest[:4], segmentMagic) {
83				return nil, nil, ErrCorruptSegment
84			}
85			seq := binary.LittleEndian.Uint64(rest[4:12])
86			count := binary.LittleEndian.Uint32(rest[12:16])
