105				records = append(records, rec)
106			}
107			if len(data)-pos < 4 {
108				return batches, tail, nil
109			}
110			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
111			if crc32.ChecksumIEEE(data[off:pos]) != crc {
112				return nil, nil, ErrCorruptSegment
113			}
114			pos += 4
115			batches = append(batches, parsedBatch{seq: seq, records: records})
