273			}
274			if err := os.WriteFile(files[0], mutate(data), 0o644); err != nil {
275				t.Fatal(err)
276			}
277			return dir
278		}
279	
280		t.Run("tampered", func(t *testing.T) {
281			dir := newCorruptLog(t, func(d []byte) []byte {
282				d[20] ^= 0xff // a payload byte: checksum mismatch
283				return d
284			})
285			if _, err := log.Open(dir, log.Options{SegmentBytes: 1 << 20}); !errors.Is(err, log.ErrCorruptSegment) {
286				t.Fatalf("Open err = %v, want ErrCorruptSegment", err)
