290			// Only the last segment may end in a crash tail; a torn
291			// earlier segment is tampering.
292			dir := t.TempDir()
293			l := open(t, dir, log.Options{SegmentBytes: 32})
294			commit(t, l, []byte("one"))
295			commit(t, l, []byte("two"))
296			l.Close()
