298			first := filepath.Join(dir, "000001.seg")
299			data, err := os.ReadFile(first)
300			if err != nil {
301				t.Fatal(err)
302			}
303			if err := os.WriteFile(first, data[:len(data)-3], 0o644); err != nil {
304				t.Fatal(err)
305			}
306			if _, err := log.Open(dir, log.Options{SegmentBytes: 32}); !errors.Is(err, log.ErrCorruptSegment) {
307				t.Fatalf("Open err = %v, want ErrCorruptSegment", err)
308			}
309		})
