358	// appendTornEntry writes a half-finished batch entry for seq to the end
359	// of the last segment file, simulating a crash mid-write.
360	func appendTornEntry(t *testing.T, dir string, seq uint64) {
361		t.Helper()
362		files, err := filepath.Glob(filepath.Join(dir, "*.seg"))
363		if err != nil || len(files) == 0 {
364			t.Fatalf("segment files = %v, %v", files, err)
365		}
366		last := files[len(files)-1]
367		var entry []byte
368		entry = append(entry, 'B', 'C', 'L', '1')
369		var tmp [8]byte
370		binary.LittleEndian.PutUint64(tmp[:], seq)
371		entry = append(entry, tmp[:]...)
372		binary.LittleEndian.PutUint32(tmp[:4], 1) // one record
373		entry = append(entry, tmp[:4]...)
374		binary.LittleEndian.PutUint32(tmp[:4], 100) // of 100 bytes
375		entry = append(entry, tmp[:4]...)
376		entry = append(entry, []byte("only-a-prefix-of-the-record")...)
377		f, err := os.OpenFile(last, os.O_WRONLY|os.O_APPEND, 0)
378		if err != nil {
379			t.Fatal(err)
380		}
381		if _, err := f.Write(entry); err != nil {
382			t.Fatal(err)
383		}
384		if err := f.Close(); err != nil {
385			t.Fatal(err)
386		}
387	}
